public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        List<npsp__DataImport__c> diList = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            if (gift != null) {
                di.npsp__Contact1_Firstname__c = gift.firstName;
                di.npsp__Contact1_Lastname__c = gift.lastName;
                di.npsp__Contact1_Personal_Email__c = gift.email;
                di.npsp__Donation_Amount__c = gift.amount;
                di.npsp__Donation_Date__c = gift.giftDate;
                di.npsp__Donation_Donor__c = 'Contact1';
            }
            diList.add(di);
        }

        insert diList;

        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getInstance();
        if (diSettings == null) {
            diSettings = npsp__Data_Import_Settings__c.getOrgDefaults();
        }
        if (diSettings == null) {
            diSettings = new npsp__Data_Import_Settings__c();
        }

        if (String.isBlank(diSettings.npsp__Contact_Matching_Rule__c)) {
            diSettings.npsp__Contact_Matching_Rule__c = 'Firstname,Lastname,Email';
        }
        if (String.isBlank(diSettings.npsp__Donation_Matching_Behavior__c)) {
            diSettings.npsp__Donation_Matching_Behavior__c = 'Do Not Match';
        }
        if (diSettings.npsp__Batch_Size__c == null) {
            diSettings.npsp__Batch_Size__c = 200;
        }

        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, diList, true);

        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :diList
        ]);

        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c staged : diList) {
            npsp__DataImport__c processed = processedMap.get(staged.Id);
            ImportResult res = new ImportResult();
            res.success = (processed != null && processed.npsp__Status__c == 'Imported');
            if (processed != null) {
                res.contactId = processed.npsp__Contact1Imported__c;
                res.opportunityId = processed.npsp__DonationImported__c;
                if (!res.success) {
                    res.errorMessage = processed.npsp__FailureInformation__c;
                }
            }
            results.add(res);
        }

        return results;
    }
}
