public with sharing class HouseholdService {
    /**
     * Creates a single NPSP Household Account for the given contacts,
     * assigning the first contact as the household's primary contact.
     *
     * @param members List of new contacts to add to the household.
     * @return Id of the created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('Member contact cannot be null.');
            }
        }

        // Inserting the first contact with no AccountId causes NPSP to automatically
        // create and name the Household Account and set the primary contact.
        Contact primary = members[0];
        insert primary;

        Contact insertedPrimary = [SELECT AccountId FROM Contact WHERE Id = :primary.Id];
        Id householdId = insertedPrimary.AccountId;
        primary.AccountId = householdId;

        // Associate any remaining contacts with the newly created Household Account
        if (members.size() > 1) {
            List<Contact> otherMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
                otherMembers.add(members[i]);
            }
            insert otherMembers;
        }

        // Ensure the Household Account record type and primary contact match requirements
        Schema.RecordTypeInfo hhRtInfo = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName().get('HH_Account');
        Id hhRecordTypeId = hhRtInfo != null ? hhRtInfo.getRecordTypeId() : null;

        Account hh = [SELECT Id, RecordTypeId, npe01__One2OneContact__c FROM Account WHERE Id = :householdId];
        Boolean needsUpdate = false;

        if (hhRecordTypeId != null && hh.RecordTypeId != hhRecordTypeId) {
            hh.RecordTypeId = hhRecordTypeId;
            needsUpdate = true;
        }
        if (hh.npe01__One2OneContact__c != primary.Id) {
            hh.npe01__One2OneContact__c = primary.Id;
            needsUpdate = true;
        }
        if (needsUpdate) {
            update hh;
        }

        return householdId;
    }
}
