```apex
public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    public static final String DUPLICATE_ERROR = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicates((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        preventDuplicates((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void preventDuplicates(List<Contact> triggerNew, List<Contact> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Boolean isInsert = (triggerOld == null);
        Map<Id, Contact> triggerNewMap = new Map<Id, Contact>();
        if (!isInsert) {
            for (Contact con : triggerNew) {
                if (con.Id != null) {
                    triggerNewMap.put(con.Id, con);
                }
            }
        }

        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newCon = triggerNew[i];
            if (newCon.AccountId == null || String.isBlank(newCon.Email)) {
                continue;
            }

            if (isInsert) {
                candidates.add(newCon);
                accountIds.add(newCon.AccountId);
                emails.add(newCon.Email.trim());
            } else {
                Contact oldCon = triggerOld[i];
                Boolean emailChanged = (newCon.Email != oldCon.Email);
                Boolean accountChanged = (newCon.AccountId != oldCon.AccountId);
                if (emailChanged || accountChanged) {
                    candidates.add(newCon);
                    accountIds.add(newCon.AccountId);
                    emails.add(newCon.Email.trim());
                }
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> existingAccountEmailToContactIds = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
        ]) {
            if (triggerNewMap.containsKey(existing.Id)) {
                Contact inTrigger = triggerNewMap.get(existing.Id);
                if (inTrigger.AccountId != existing.AccountId ||
                    inTrigger.Email == null ||
                    !inTrigger.Email.equalsIgnoreCase(existing.Email)) {
                    continue;
                }
            }

            String key = buildCompositeKey(existing.AccountId, existing.Email);
            if (!existingAccountEmailToContactIds.containsKey(key)) {
                existingAccountEmailToContactIds.put(key, new Set<Id>());
            }
            existingAccountEmailToContactIds.get(key).add(existing.Id);
        }

        Set<String> seenInThisSave = new Set<String>();
        for (Contact candidate : candidates) {
            String key = buildCompositeKey(candidate.AccountId, candidate.Email);

            if (seenInThisSave.contains(key)) {
                candidate.addError(DUPLICATE_ERROR);
                continue;
            }

            Set<Id> existingContactIds = existingAccountEmailToContactIds.get(key);
            if (existingContactIds != null) {
                Boolean hasConflict = false;
                for (Id existingId : existingContactIds) {
                    if (candidate.Id == null || existingId != candidate.Id) {
                        hasConflict = true;
                        break;
                    }
                }
                if (hasConflict) {
                    candidate.addError(DUPLICATE_ERROR);
                    continue;
                }
            }

            seenInThisSave.add(key);
        }
    }

    private String buildCompositeKey(Id accountId, String email) {
        return String.valueOf(accountId) + '#' + (email != null ? email.trim().toLowerCase() : '');
    }
}
